module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out_sop,
  output out_pos
);

  wire pos0, pos1;
  assign out_sop = c&d | ~a&~b&c;
  assign pos0 = c & (~b|d)&(~a|b);
  assign pos1 = c & (~b|d)&(~a|d);

  assign out_pos = (pos0 == pos1) ? pos0 : 1'bx;

endmodule

module TopModule (
    input a,
    input b,
    input c,
    input d,
    output out_sop,
    output out_pos
);

    // SOP implementation
    assign out_sop = (a & ~b & ~c & ~d) | // 7
                     (~a & b & ~c & ~d) | // 15
                     (~a & ~b & c & ~d);   // 2

    // POS implementation
    wire not_a = ~a;
    wire not_b = ~b;
    wire not_c = ~c;
    wire not_d = ~d;

    assign out_pos = not_a | not_b | not_c | not_d; // 0, 1, 4, 5, 6, 9, 10, 13, 14

endmodule

