    localparam [2:0] C = 3'b010;
    localparam [2:0] D = 3'b011;
    localparam [2:0] E = 3'b100;
    localparam [2:0] F = 3'b101;

    // Current state register
    reg [2:0] currentState;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            currentState <= A; // Reset to initial state A
        end else begin
            case (currentState)
                A:
                    currentState <= (w == 1'b0) ? B : A;
                B:
                    currentState <= (w == 1'b0) ? C : D;
                C:
                    currentState <= (w == 1'b0) ? E : D;
                D:
                    currentState <= (w == 1'b0) ? F : A;
                E:
                    currentState <= (w == 1'b1) ? D : E;
                F:
                    currentState <= (w == 1'b0) ? C : D;
                default:
                    currentState <= A; // Default to state A
            endcase
        end
    end

    // Output assignment based on current state
    assign z = (currentState == E || currentState == F);

endmodule

module TopModule (
