);

    localparam IDLE = 2'b00;
    localparam FIND_FIRST_BYTE = 2'b01;
    localparam RECEIVE_MESSAGE = 2'b10;

    reg [1:0] state;
    reg [7:0] message_buffer [0:2];
    integer idx;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            out_bytes <= 24'b0;
            done <= 0;
            idx <= 0;
        end else begin
            case (state)
                IDLE:
                    begin
                        if (in[3]) begin
                            state <= FIND_FIRST_BYTE;
                            idx <= 0;
                            message_buffer[idx] <= in;
                        end
                    end
                FIND_FIRST_BYTE:
                    begin
                        if (idx == 2) begin
                            state <= RECEIVE_MESSAGE;
                        end else begin
                            if (in[3]) begin
                                idx <= idx + 1;
                                message_buffer[idx] <= in;
                            end
                        end
                    end
                RECEIVE_MESSAGE:
                    begin
                        done <= 1;
                        out_bytes <= {message_buffer[2], message_buffer[1], message_buffer[0]};
                        state <= IDLE;
                    end
                default:
                    state <= IDLE;
            endcase
        end
    end

endmodule

